def is_prime(n):
    """Check if a number is prime using the 6k +/- 1 optimization."""
    # 1 and numbers less than 1 are not prime
    if n <= 1:
        return False

    # 2 and 3 are prime numbers
    if n <= 3:
        return True

    # Eliminate even numbers and multiples of 3
    if n % 2 == 0 or n % 3 == 0:
        return False

    # All other primes are of the form 6k +/- 1.
    # We only need to check factors up to the square root of n.
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
